using System.Net;

namespace QuicNet.Geolocation;

public static class AccessTopologyAnalyzer
{
    public static AccessTopology Analyze(MeasurementSession session, EmbeddedCatalog? catalog = null)
    {
        var data = catalog ?? EmbeddedCatalog.Default;
        var routes = session.Observations.Where(o => o.Route.Count > 0).Take(64).ToArray();
        var shared = routes.SelectMany(o => o.Route.Where(h => h.Status == "TtlExpired" &&
                IPAddress.TryParse(h.Address, out var ip) && EmbeddedCatalog.IsPublic(ip))
                .GroupBy(h => h.Address).Select(g => (Observation: o, Hop: g.OrderBy(h => h.Ttl).First())))
            .GroupBy(x => x.Hop.Address!, StringComparer.Ordinal)
            .Where(g => g.Select(x => x.Observation.LandmarkId).Distinct().Count() >= 2)
            .Select(g => new SharedRouter(g.Key, g.Min(x => x.Hop.Ttl), g.Select(x => x.Observation.LandmarkId).Distinct().Count(),
                g.Where(x => x.Hop.RttMs.HasValue).Select(x => x.Hop.RttMs).DefaultIfEmpty(null).Min(),
                data.LookupAsn(IPAddress.Parse(g.Key)), data.LookupRouter(IPAddress.Parse(g.Key))))
            .OrderBy(r => r.MinimumTtl).ThenByDescending(r => r.Paths).ToArray();
        var pairs = new List<RoutePair>();
        for (int a = 0; a < routes.Length; a++) for (int b = a + 1; b < routes.Length; b++)
        {
            // Require all repeats at a TTL to agree before it participates in a stable prefix.
            var left = Stable(routes[a]); var right = Stable(routes[b]);
            int common = 0; int? divergence = null; bool missing = false;
            int max = Math.Min(routes[a].Route.Max(h => h.Ttl), routes[b].Route.Max(h => h.Ttl));
            for (int ttl = 1; ttl <= max; ttl++)
            {
                if (!left.TryGetValue(ttl, out var l) || !right.TryGetValue(ttl, out var r)) { missing = true; break; }
                if (l != r) { divergence = ttl; break; }
                common++;
            }
            pairs.Add(new(routes[a].LandmarkId, routes[b].LandmarkId, common, divergence, missing));
        }
        return new(shared, pairs.ToArray(), routes.Length,
            "Shared routers describe observed access topology, not subscriber municipalities. Missing/load-balanced hops are not equal. Adjacent RTTs are not link delays.");
    }
    private static Dictionary<int, string> Stable(Observation observation) => observation.Route
        .GroupBy(h => h.Ttl).Where(g => g.All(h => h.Address != null && h.Status is "TtlExpired" or "Success") &&
            g.Select(h => h.Address).Distinct(StringComparer.Ordinal).Count() == 1)
        .ToDictionary(g => g.Key, g => g.First().Address!);
}

